require('dotenv').config();
const express = require('express');
const session = require('express-session');
const PgStore = require('connect-pg-simple')(session);
const { Pool } = require('pg');
const bcrypt = require('bcryptjs');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const multer = require('multer');
const ExcelJS = require('exceljs');
const crypto = require('node:crypto');
const fs = require('node:fs/promises');
const path = require('node:path');

const app = express();
const isProd = process.env.NODE_ENV === 'production';
const port = Number(process.env.PORT || 3000);
const pool = new Pool({ connectionString: process.env.DATABASE_URL, options: '-c timezone=America/Sao_Paulo', ssl: process.env.PGSSLMODE === 'verify-full' ? { rejectUnauthorized: true } : undefined, max: 10 });
let dummyPasswordHash;
const roles = ['admin', 'owner', 'finance', 'operations', 'auditor'];
const roleLabels = { admin: 'Administrador', owner: 'Proprietário/Gestor', finance: 'Financeiro', operations: 'Operação', auditor: 'Consulta/Auditoria' };
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: (Number(process.env.MAX_UPLOAD_MB) || 10) * 1024 * 1024, files: 1 } });
const loginLogoUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024, files: 1 } });
const loginLogoTypes = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };

function fail(res, status, message) { return res.status(status).json({ error: message }); }
function id() { return crypto.randomUUID(); }
function receiveLoginLogo(req, res, next) {
  loginLogoUpload.single('file')(req, res, error => {
    if (error instanceof multer.MulterError) return fail(res, 413, 'A logo deve ter no máximo 5 MB.');
    if (error) return next(error);
    next();
  });
}
function brandingDir() { return path.join(path.resolve(process.env.UPLOAD_DIR || path.join(__dirname, 'data', 'uploads')), 'branding'); }
async function readLoginLogo() {
  const directory = brandingDir();
  try {
    const metadata = JSON.parse(await fs.readFile(path.join(directory, 'login-logo.json'), 'utf8'));
    const extension = loginLogoTypes[metadata.mime_type];
    if (!extension || !new RegExp(`^login-logo-[0-9a-f-]+\\.${extension}$`).test(metadata.file_name || '')) return null;
    const filePath = path.join(directory, metadata.file_name);
    await fs.access(filePath);
    return { ...metadata, file_path: filePath };
  } catch { return null; }
}
function detectLoginLogoType(buffer) {
  if (buffer.length >= 8 && buffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) return 'image/png';
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) return 'image/jpeg';
  if (buffer.length >= 12 && buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP') return 'image/webp';
  return null;
}
function parseMoney(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? Math.round(value * 100) : null;
  if (value === null || value === undefined || String(value).trim() === '') return null;
  let s = String(value).trim().replace(/R\$|\s/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n * 100) : null;
}
function parseQty(value) { const n = Number(String(value ?? '').replace(',', '.')); return Number.isFinite(n) && n > 0 ? n : null; }
function validDate(v) { return /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) && !Number.isNaN(Date.parse(`${v}T12:00:00Z`)); }
function normalizeDate(v) { const s=String(v??'').trim(); if(validDate(s))return s; const m=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/); if(!m)return null; const iso=`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`; return validDate(iso)?iso:null; }
function localToday() { return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()); }
function localDateAfter(days) { return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(Date.now()+days*86400000)); }
function text(v, max = 250) { return String(v ?? '').trim().slice(0, max); }
function jsonable(v) { return v === undefined ? null : v; }
async function periodIsClosed(unitId,date,queryable=pool){if(!validDate(date))return false;const month=date.slice(0,7)+'-01';const result=await queryable.query("SELECT 1 FROM period_closures WHERE unit_id=$1 AND month_start=$2::date AND status='closed'",[unitId,month]);return result.rowCount>0;}

async function migrate() {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query('SELECT pg_advisory_xact_lock(648273910)');
    await client.query('CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())');
    const files = (await fs.readdir(path.join(__dirname, 'migrations'))).filter(f => f.endsWith('.sql')).sort();
    for (const file of files) {
      const exists = await client.query('SELECT 1 FROM schema_migrations WHERE version=$1', [file]);
      if (!exists.rowCount) {
        await client.query(await fs.readFile(path.join(__dirname, 'migrations', file), 'utf8'));
        await client.query('INSERT INTO schema_migrations(version) VALUES($1)', [file]);
      }
    }
    await client.query('COMMIT');
  } catch (e) { await client.query('ROLLBACK'); throw e; } finally { client.release(); }
}
async function audit(client, req, unitId, action, entityType, entityId, beforeData, afterData, reason = null) {
  await client.query(`INSERT INTO audit_log(id,unit_id,user_id,action,entity_type,entity_id,reason,before_data,after_data,request_id)
    VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9::jsonb,$10)`, [id(), unitId, req.session.user.id, action, entityType, entityId || null, reason, JSON.stringify(jsonable(beforeData)), JSON.stringify(jsonable(afterData)), req.id]);
}
async function inTx(fn) {
  const client = await pool.connect();
  try { await client.query('BEGIN'); const value = await fn(client); await client.query('COMMIT'); return value; }
  catch (e) { await client.query('ROLLBACK'); throw e; } finally { client.release(); }
}

app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use((req, res, next) => { req.id = crypto.randomUUID(); res.setHeader('X-Request-Id', req.id); next(); });
app.use(helmet({ contentSecurityPolicy: { directives: { defaultSrc: ["'self'"], scriptSrc: ["'self'"], styleSrc: ["'self'"], styleSrcAttr: ["'unsafe-inline'"], imgSrc: ["'self'", 'data:'], connectSrc: ["'self'"], objectSrc: ["'none'"], frameAncestors: ["'none'"] } }, crossOriginEmbedderPolicy: false }));
app.use(express.json({ limit: '1mb' }));
app.use(session({
  store: new PgStore({ pool, createTableIfMissing: true, tableName: 'app_sessions' }),
  name: 'villa.sid', secret: process.env.SESSION_SECRET,
  resave: false, saveUninitialized: false, rolling: true,
  cookie: { httpOnly: true, secure: isProd, sameSite: 'lax', maxAge: 8 * 60 * 60 * 1000 }
}));

function requireAuth(req, res, next) {
  if (!req.session.user) return fail(res, 401, 'Faça login para continuar.');
  next();
}
function allow(...allowed) {
  return (req, res, next) => {
    if (!req.session.user) return fail(res, 401, 'Faça login para continuar.');
    if (!allowed.includes(req.session.user.role)) return fail(res, 403, 'Seu perfil não permite esta ação.');
    next();
  };
}
function csrf(req, res, next) {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  const sent = req.get('X-CSRF-Token') || '';
  const expected = req.session.csrf || '';
  const sentBytes = Buffer.from(sent);
  const expectedBytes = Buffer.from(expected);
  if (!/^[0-9a-f]{64}$/.test(sent) || sentBytes.length !== expectedBytes.length || !crypto.timingSafeEqual(sentBytes, expectedBytes)) return fail(res, 403, 'Sessão expirada ou token de segurança inválido. Atualize a página.');
  next();
}
app.use('/api', (req, res, next) => { res.setHeader('Cache-Control', 'no-store'); next(); });
app.use('/api', csrf);
app.get('/api/public/login-logo', async (req, res, next) => {
  try {
    res.setHeader('Cache-Control', 'no-store, max-age=0');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    const logo = await readLoginLogo();
    if (logo) { res.type(logo.mime_type); return res.sendFile(logo.file_path); }
    res.type('image/png');
    res.sendFile(path.join(__dirname, 'public', 'villa-cruz-logo.png'));
  } catch (e) { next(e); }
});

const authLimit = rateLimit({ windowMs: 15 * 60 * 1000, limit: 12, standardHeaders: 'draft-7', legacyHeaders: false, handler: (req, res) => fail(res, 429, 'Não foi possível autenticar agora. Aguarde alguns minutos e tente novamente.') });
app.get('/api/auth/csrf', (req, res) => { req.session.csrf ||= crypto.randomBytes(32).toString('hex'); res.json({ token: req.session.csrf }); });
app.post('/api/auth/login', authLimit, async (req, res, next) => {
  try {
    const rawEmail = req.body?.email;
    const rawPassword = req.body?.password;
    const email = typeof rawEmail === 'string' ? rawEmail.trim().toLowerCase() : '';
    const password = typeof rawPassword === 'string' ? rawPassword : '';
    const validEmail = email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    const validPassword = password.length > 0 && Buffer.byteLength(password, 'utf8') <= 72;
    const userResult = validEmail ? await pool.query('SELECT id,name,email,password_hash,role,active,must_change_password FROM users WHERE email=$1', [email]) : { rows: [] };
    const user = userResult.rows[0];
    const passwordMatches = await bcrypt.compare(validPassword ? password : 'invalid-credential', user?.password_hash || dummyPasswordHash);
    const ok = validEmail && validPassword && user?.active && passwordMatches;
    if (!ok) return fail(res, 401, 'E-mail ou senha inválidos.');
    req.session.regenerate(err => {
      if (err) return next(err);
      req.session.user = { id: user.id, name: user.name, role: user.role, roleLabel: roleLabels[user.role], mustChangePassword: user.must_change_password };
      req.session.csrf = crypto.randomBytes(32).toString('hex');
      req.session.save(err2 => err2 ? next(err2) : res.json({ user: req.session.user, csrf: req.session.csrf }));
    });
  } catch (e) { next(e); }
});
app.post('/api/auth/change-password', authLimit, requireAuth, async (req, res, next) => {
  try {
    if (!req.session.user.mustChangePassword) return fail(res, 403, 'A troca obrigatória de senha não está pendente nesta sessão.');
    const currentPassword = typeof req.body?.current_password === 'string' ? req.body.current_password : '';
    const newPassword = typeof req.body?.new_password === 'string' ? req.body.new_password : '';
    const confirmation = typeof req.body?.confirm_password === 'string' ? req.body.confirm_password : '';
    if (newPassword.length < 12 || Buffer.byteLength(newPassword, 'utf8') > 72) return fail(res, 400, 'A nova senha deve ter pelo menos 12 caracteres e no máximo 72 bytes em UTF-8.');
    if (newPassword !== confirmation) return fail(res, 400, 'A confirmação da senha não confere.');
    const found = await pool.query('SELECT password_hash,active FROM users WHERE id=$1', [req.session.user.id]);
    if (!found.rowCount || !found.rows[0].active) return fail(res, 401, 'Conta indisponível. Entre novamente.');
    if (!await bcrypt.compare(currentPassword, found.rows[0].password_hash)) return fail(res, 400, 'A senha atual está incorreta.');
    if (await bcrypt.compare(newPassword, found.rows[0].password_hash)) return fail(res, 400, 'Escolha uma senha diferente da senha atual.');
    const passwordHash = await bcrypt.hash(newPassword, 12);
    const updated = await pool.query('UPDATE users SET password_hash=$1,must_change_password=false,updated_at=now() WHERE id=$2 AND password_hash=$3 AND must_change_password=true RETURNING id', [passwordHash, req.session.user.id, found.rows[0].password_hash]);
    if (!updated.rowCount) return fail(res, 409, 'A senha já foi alterada. Entre novamente com a nova senha.');
    await pool.query("DELETE FROM app_sessions WHERE sess->'user'->>'id'=$1", [req.session.user.id]);
    await audit(pool, req, 'villa-cruz', 'change', 'user_password', req.session.user.id, null, { must_change_password: false });
    const user = { ...req.session.user, mustChangePassword: false };
    req.session.regenerate(err => {
      if (err) return next(err);
      req.session.user = user;
      req.session.csrf = crypto.randomBytes(32).toString('hex');
      req.session.save(err2 => err2 ? next(err2) : res.json({ user, csrf: req.session.csrf }));
    });
  } catch (e) { next(e); }
});
