app.post('/api/sales', allow('admin','owner','finance','operations'), async (req,res,next)=>{
  try {
    const u=await routeUnit(req,res); if(!u)return; const d=req.body;
    const amount=parseMoney(d.amount); const target=d.target===''||d.target==null?null:parseMoney(d.target);
    if(!validDate(d.sale_date)||amount===null||amount<0) return fail(res,400,'Informe uma data válida e um faturamento igual ou maior que zero.');
    if(await periodIsClosed(u.id,d.sale_date))return fail(res,409,'Este período está fechado. Reabra o mês com justificativa antes de lançar faturamento.');
    const row={id:id(),unit_id:u.id,sale_date:d.sale_date,channel:text(d.channel||'Salão',80),amount_cents:amount,target_cents:target,notes:text(d.notes,2000),status:'confirmed',created_by:req.session.user.id};
    await inTx(async c=>{await c.query(`INSERT INTO sales(id,unit_id,sale_date,channel,amount_cents,target_cents,notes,status,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,Object.values(row)); await audit(c,req,u.id,'create','sale',row.id,null,row);});
    res.status(201).json(row);
  }catch(e){next(e);}
});

app.get('/api/sales/comparison', async(req,res,next)=>{
  try{
    const u=await routeUnit(req,res);if(!u)return;
    const today=localToday(),month=today.slice(0,7);
    const from=validDate(req.query.from)?req.query.from:month+'-01';
    const to=validDate(req.query.to)?req.query.to:today;
    if(from>to)return fail(res,400,'A data inicial deve ser anterior ou igual à data final.');
    const days=Math.floor((Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000)+1;
    const previousTo=new Date(Date.parse(from+'T00:00:00Z')-86400000).toISOString().slice(0,10);
    const previousFrom=new Date(Date.parse(previousTo+'T00:00:00Z')-(days-1)*86400000).toISOString().slice(0,10);
    const result=await pool.query("SELECT channel,COALESCE(sum(amount_cents) FILTER(WHERE sale_date BETWEEN $2 AND $3 AND status=$6),0)::text current_cents,COALESCE(sum(amount_cents) FILTER(WHERE sale_date BETWEEN $4 AND $5 AND status=$6),0)::text previous_cents FROM sales WHERE unit_id=$1 AND sale_date BETWEEN $4 AND $3 GROUP BY channel ORDER BY channel",[u.id,from,to,previousFrom,previousTo,'confirmed']);
    const totals=result.rows.reduce((a,r)=>({current:(BigInt(a.current)+BigInt(r.current_cents)).toString(),previous:(BigInt(a.previous)+BigInt(r.previous_cents)).toString()}),{current:'0',previous:'0'});
    res.json({period:{from,to},previous_period:{from:previousFrom,to:previousTo},totals,channels:result.rows});
  }catch(e){next(e);}
});
