async function productFields(d,unitId){const minimum=d.minimum_quantity==null||d.minimum_quantity===''?0:Number(String(d.minimum_quantity).replace(',','.')),target=d.target_quantity==null||d.target_quantity===''?minimum:Number(String(d.target_quantity).replace(',','.')),leadDays=Number(d.supplier_lead_days||0),conversion=d.purchase_to_base_quantity==null||d.purchase_to_base_quantity===''?1:Number(String(d.purchase_to_base_quantity).replace(',','.'));if(!text(d.name,160)||!Number.isFinite(minimum)||minimum<0||!Number.isFinite(target)||target<minimum||!Number.isFinite(conversion)||conversion<=0||conversion>1000000||!Number.isInteger(leadDays)||leadDays<0||leadDays>365)return {error:'Informe nome, estoque mínimo, estoque desejado (igual ou maior que o mínimo) e prazo válido.'};const baseUnits=['kg','g','mg','l','ml','unidade','dúzia','par','metro','centímetro','m²','m³'];const purchaseUnits=['unidade','caixa','pacote','fardo','saco','garrafa','lata','pote','bandeja','dúzia','rolo','galão','frasco','peça','kit'];const baseUnit=text(d.base_unit||'unidade',30),purchaseUnit=text(d.purchase_unit||'unidade',30);if(!baseUnits.includes(baseUnit))return {error:'Selecione uma unidade-base válida.'};if(!purchaseUnits.includes(purchaseUnit))return {error:'Selecione uma unidade de compra válida.'};const itemType=text(d.item_type||'Ingrediente',60);const expiry=Number(d.expiry_alert_days??7);if(!Number.isInteger(expiry)||expiry<0||expiry>3650)return {error:'Selecione um alerta de vencimento válido.'};const [category,supplier,typeOption,alertOption]=await Promise.all([d.category_id?pool.query("SELECT id FROM categories WHERE id=$1 AND unit_id=$2 AND kind='stock' AND active",[text(d.category_id,80),unitId]):{rowCount:1},d.supplier_id?pool.query('SELECT id FROM suppliers WHERE id=$1 AND unit_id=$2 AND active',[text(d.supplier_id,80),unitId]):{rowCount:1},pool.query('SELECT id FROM product_catalog_options WHERE unit_id=$1 AND kind=$2 AND value=$3',[unitId,'item_type',itemType.toLocaleLowerCase('pt-BR')]),pool.query('SELECT id FROM product_catalog_options WHERE unit_id=$1 AND kind=$2 AND value=$3',[unitId,'expiry_alert',String(expiry)])]);if(!category.rowCount)return {error:'Categoria de estoque inválida para esta unidade.'};if(!supplier.rowCount)return {error:'Fornecedor inválido para esta unidade.'};const defaults=['Ingrediente','Bebida','Embalagem','Limpeza','Utensílio','Outro'];if(!defaults.includes(itemType)&&!typeOption.rowCount)return {error:'Tipo de item não cadastrado.'};if(![0,3,7,15,30].includes(expiry)&&!alertOption.rowCount)return {error:'Alerta de vencimento não cadastrado.'};return {row:{name:text(d.name,160),sku:text(d.sku,80)||null,category_id:text(d.category_id,80)||null,base_unit:baseUnit,purchase_unit:purchaseUnit,purchase_to_base_quantity:conversion,minimum_quantity:minimum,item_type:itemType,expiry_alert_days:expiry,supplier_id:text(d.supplier_id,80)||null,description:text(d.description,2000)||null,target_quantity:target,supplier_lead_days:leadDays}};}

