        await c.query(`INSERT INTO stock_lots(id,unit_id,product_id,supplier,supplier_id,received_on,quantity_received,quantity_remaining,unit_cost_cents,purchase_quantity,purchase_unit,package_cost_cents,purchase_to_base_quantity,cost_normalized,source_document,purchase_order_item_id,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$7,round($8/$9),$10,$11,$8,$9,true,$12,$13,$14)`,[lotId,u.id,x.product_id,supplier.rows[0].name,order.rows[0].supplier_id,receivedOn,baseQty,packageCost,x.conversion,qty,x.purchase_unit,text(item.source_document,120)||null,x.id,req.session.user.id]);
