// Fluxo financeiro: contas bancárias e movimentações entre bancos e caixa da loja.
const bankOperations={deposit:'Depósito do caixa no banco',withdrawal:'Saque do banco para o caixa',transfer:'Transferência entre contas',receipt:'Recebimento no banco',payment:'Pagamento pelo banco',fee:'Tarifa bancária'};
const bankAccountTypes=['checking','savings','digital','other'];
const bankBalanceSql=`(ba.opening_cents+COALESCE(sum(CASE WHEN bm.direction='in' THEN bm.amount_cents ELSE -bm.amount_cents END),0))::text`;
function moneyText(cents){return (Number(cents)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});}
function addDays(date,days){return new Date(Date.parse(`${date}T12:00:00Z`)+days*86400000).toISOString().slice(0,10);}
async function bankAccountRows(db,unitId){
  const r=await db.query(`SELECT ba.id,ba.name,ba.bank_name,ba.account_type,ba.opening_cents::text opening_cents,ba.opening_date::text opening_date,ba.active,${bankBalanceSql} balance_cents FROM bank_accounts ba LEFT JOIN bank_movements bm ON bm.account_id=ba.id WHERE ba.unit_id=$1 GROUP BY ba.id ORDER BY ba.active DESC,lower(ba.name)`,[unitId]);
  return r.rows;
}
async function bankBalance(db,accountId){
  const r=await db.query(`SELECT ${bankBalanceSql} balance_cents FROM bank_accounts ba LEFT JOIN bank_movements bm ON bm.account_id=ba.id WHERE ba.id=$1 GROUP BY ba.id`,[accountId]);
  return BigInt(r.rows[0].balance_cents);
}
async function sessionExpected(db,sessionId){
  const r=await db.query(`SELECT COALESCE(sum(CASE WHEN movement_type IN ('opening','inflow') THEN amount_cents ELSE -amount_cents END),0)::text amount FROM cash_movements WHERE session_id=$1`,[sessionId]);
  return BigInt(r.rows[0].amount);
}
async function cashOnHand(db,unitId){
  const open=await db.query('SELECT id,shift_name FROM cash_sessions WHERE unit_id=$1 AND closed_at IS NULL ORDER BY opened_at DESC LIMIT 1',[unitId]);
  if(open.rowCount)return {cents:(await sessionExpected(db,open.rows[0].id)).toString(),source:'open',shift_name:open.rows[0].shift_name};
  const last=await db.query('SELECT counted_cents::text counted_cents,shift_name FROM cash_sessions WHERE unit_id=$1 AND closed_at IS NOT NULL ORDER BY closed_at DESC LIMIT 1',[unitId]);
  return last.rowCount?{cents:last.rows[0].counted_cents,source:'closed',shift_name:last.rows[0].shift_name}:{cents:'0',source:'none',shift_name:null};
}
