    res.json({month,period:{from:start,to:end},closure:closure.rows[0]||null,checks:closure.rows[0]?.checklist||{},stats:{sales:Number(sales.rows[0].count),unclassified_expenses:Number(unclassified.rows[0].count),open_cash_sessions:Number(openCash.rows[0].count)}});
