app.get('/api/audit',allow('admin','owner','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const values=[u.id],where=['a.unit_id=$1'];for(const [key,expr,max] of [['action','a.action',40],['entity_type','a.entity_type',60],['entity_id','a.entity_id',100]]){const value=text(req.query[key],max);if(value){values.push(`%${value.replace(/[\\%_]/g,'\\$&')}%`);where.push(`${expr} ILIKE $${values.length} ESCAPE '\\'`);}}const from=validDate(req.query.from)?req.query.from:null,to=validDate(req.query.to)?req.query.to:null;if(from){values.push(from);where.push(`a.created_at >= $${values.length}::date`);}if(to){values.push(to);where.push(`a.created_at < ($${values.length}::date + interval '1 day')`);}const actor=text(req.query.user_id,100);if(actor){values.push(actor);where.push(`a.user_id=$${values.length}`);}const r=await pool.query(`SELECT a.id,a.action,a.entity_type,a.entity_id,a.reason,a.before_data,a.after_data,a.created_at,u.name user_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE ${where.join(' AND ')} ORDER BY a.created_at DESC LIMIT 500`,values);res.json(r.rows);}catch(e){next(e);}});
