app.get('/api/products/audit',allow('admin','owner','auditor'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT p.id,p.name,p.sku,p.created_at,p.updated_at,creator.name created_by_name,last_change.user_name updated_by_name,last_change.created_at changed_at,last_change.before_data,last_change.after_data FROM products p LEFT JOIN users creator ON creator.id=p.created_by LEFT JOIN LATERAL(SELECT a.created_at,a.before_data,a.after_data,actor.name user_name FROM audit_log a LEFT JOIN users actor ON actor.id=a.user_id WHERE a.unit_id=p.unit_id AND a.entity_type='product' AND a.entity_id=p.id AND a.action='update' ORDER BY a.created_at DESC LIMIT 1) last_change ON true WHERE p.unit_id=$1 ORDER BY COALESCE(last_change.created_at,p.created_at) DESC LIMIT 300`,[u.id]);res.json(r.rows);}catch(e){next(e);}});
