app.post('/api/admin/users',allow('admin'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const d=req.body;const email=text(d.email,254).toLowerCase(),name=text(d.name,120),role=roles.includes(d.role)?d.role:null,password=String(d.password||'');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||!name||!role||password.length<12||Buffer.byteLength(password,'utf8')>72)return fail(res,400,'Informe nome, e-mail válido, perfil e senha temporária com pelo menos 12 caracteres e até 72 bytes em UTF-8.');const hash=await bcrypt.hash(password,12);const user={id:id(),name,email,hash,role};await inTx(async c=>{await c.query('INSERT INTO users(id,name,email,password_hash,role,must_change_password) VALUES($1,$2,$3,$4,$5,true)',Object.values(user));await c.query('INSERT INTO user_units(user_id,unit_id) VALUES($1,$2)',[user.id,u.id]);await audit(c,req,u.id,'create','user',user.id,null,{name,email,role,must_change_password:true});});res.status(201).json({id:user.id,name,email,role,must_change_password:true});}catch(e){if(e.code==='23505')return fail(res,409,'Já existe usuário com este e-mail.');next(e);}});
app.patch('/api/admin/users/:id/active',allow('admin'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const active=['true','on','1'].includes(String(req.body.active).toLowerCase());const result=await inTx(async c=>{const old=await c.query('SELECT x.id,x.name,x.email,x.role,x.active FROM users x JOIN user_units uu ON uu.user_id=x.id WHERE x.id=$1 AND uu.unit_id=$2 FOR UPDATE OF x',[req.params.id,u.id]);if(!old.rowCount)return null;if(!active&&old.rows[0].role==='admin'){await c.query('SELECT b.id FROM business_units b JOIN user_units uu ON uu.unit_id=b.id WHERE uu.user_id=$1 ORDER BY b.id FOR UPDATE OF b',[req.params.id]);const otherUnits=await c.query("SELECT uu.unit_id FROM user_units uu WHERE uu.user_id=$1 AND NOT EXISTS (SELECT 1 FROM users x JOIN user_units ux ON ux.user_id=x.id WHERE ux.unit_id=uu.unit_id AND x.role='admin' AND x.active AND x.id<>$1)",[req.params.id]);if(otherUnits.rowCount)return {error:'Este usuário é o último administrador ativo de uma ou mais unidades.'};}const updated=await c.query('UPDATE users SET active=$1,updated_at=now() WHERE id=$2 RETURNING id,name,email,role,active',[active,req.params.id]);if(!active)await c.query("DELETE FROM app_sessions WHERE sess->'user'->>'id'=$1",[req.params.id]);await audit(c,req,u.id,active?'activate':'deactivate','user',req.params.id,old.rows[0],updated.rows[0],text(req.body.reason,300)||null);return updated.rows[0];});if(!result)return fail(res,404,'Usuário não encontrado nesta unidade.');if(result.error)return fail(res,409,result.error);res.json(result);}catch(e){next(e);}});

